def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be an integer in range 1..3999")
    if n < 1 or n > 3999:
        raise ValueError("Input must be an integer in range 1..3999")

    val_map = [
        (1000, "M"),
        (900, "CM"),
        (500, "D"),
        (400, "CD"),
        (100, "C"),
        (90, "XC"),
        (50, "L"),
        (40, "XL"),
        (10, "X"),
        (9, "IX"),
        (5, "V"),
        (4, "IV"),
        (1, "I"),
    ]

    result = []
    remaining = n
    for value, numeral in val_map:
        while remaining >= value:
            result.append(numeral)
            remaining -= value
    return "".join(result)


_ROMAN_VALUES = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}

# Valid subtractive pairs: only I before V/X, X before C/L, C before D/M
_VALID_SUBTRACTIVES = {"I", "X", "C"}


def _is_valid_roman(s):
    """Check that s is a well-formed Roman numeral in standard subtractive notation."""
    if not s:
        return False

    values = [_ROMAN_VALUES[c] for c in s]

    # Check all characters are valid Roman numerals
    if len(values) != len(s):
        return False

    # Must be non-decreasing except for valid subtractive pairs
    for i in range(len(values) - 1):
        if values[i] >= values[i + 1]:
            continue
        # values[i] < values[i+1]: this is a subtractive pair
        if values[i] not in _ROMAN_VALUES or values[i + 1] not in _ROMAN_VALUES:
            return False
        # Valid subtractive: I(1) before V(5)/X(10), X(10) before C(100)/L(500),
        # C(100) before D(500)/M(1000)
        allowed_next = {
            1: {5, 10},
            10: {100, 500},
            100: {500, 1000},
        }
        if values[i + 1] not in allowed_next.get(values[i], set()):
            return False

    # Reconstruct the value and verify it matches
    total = 0
    for i in range(len(values)):
        if i + 1 < len(values) and values[i] < values[i + 1]:
            total += values[i + 1] - values[i]
            i += 1  # skip next (already consumed)
        else:
            total += values[i]

    # Verify round-trip: convert back and compare
    return total == from_roman(s)


def from_roman(s):
    """Convert a Roman numeral string to its integer value.

    Raises ValueError for anything that is not a well-formed numeral
    in standard subtractive notation.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Quick validation: all chars must be valid Roman numerals
    for c in s:
        if c not in _ROMAN_VALUES:
            raise ValueError(f"Invalid character: {c}")

    values = [_ROMAN_VALUES[c] for c in s]

    # Validate structure (subtractive notation rules)
    for i in range(len(values) - 1):
        if values[i] >= values[i + 1]:
            continue
        # Subtractively written: first must be smaller
        allowed_next = {
            1: {5, 10},
            10: {100, 500},
            100: {500, 1000},
        }
        if values[i + 1] not in allowed_next.get(values[i], set()):
            raise ValueError(f"Invalid subtractive combination: {s}")

    # Compute value
    total = 0
    i = 0
    while i < len(values):
        if i + 1 < len(values) and values[i] < values[i + 1]:
            total += values[i + 1] - values[i]
            i += 2
        else:
            total += values[i]
            i += 1

    # Round-trip check: ensure this is canonical
    if to_roman(total) != s:
        raise ValueError(f"Not a canonical Roman numeral: {s}")

    return total

